    "وَحَدَّثَنَاهُ أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ عُبَيْدِ اللَّهِ، بِهَذَا الإِسْنَادِ." to "وحدثناه ابو بكر بن ابي شيبه، حدثنا علي بن مسهر، عن عبيد الله، بهذا الاسناد.",
    "وَحَدَّثَنِيهِ أَبُو كَامِلٍ الْجَحْدَرِيُّ، حَدَّثَنَا حَمَّادٌ، حَدَّثَنَا أَيُّوبُ، عَنْ نَافِعٍ، بِهَذَا الإِسْنَادِ‏.‏" to "وحدثنيه ابو كامل الجحدري، حدثنا حماد، حدثنا ايوب، عن نافع، بهذا الاسناد.",
    "وَحَدَّثَنَاهُ ابْنُ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا سُفْيَانُ، بِهَذَا الإِسْنَادِ وَلَمْ يَذْكُرْ فِعْلَ عَائِشَةَ‏.‏" to "وحدثناه ابن نمير، حدثنا ابي، حدثنا سفيان، بهذا الاسناد ولم يذكر فعل عايشه.",
    "وَحَدَّثَنَا ابْنُ نُمَيْرٍ، حَدَّثَنَا أَبُو عَاصِمٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ أَبِي الزُّبَيْرِ، بِهَذَا الإِسْنَادِ بِمِثْلِهِ." to "وحدثنا ابن نمير، حدثنا ابو عاصم، عن ابن جريج، عن ابي الزبير، بهذا الاسناد بمثله.",
    "وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، أَخْبَرَنَا أَبُو ضَمْرَةَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "وحدثنا يحيي بن يحيي، اخبرنا ابو ضمره، عن عبد الرحمن بن حميد، بهذا الاسناد مثله .",
    "وَحَدَّثَنَاهُ الْحَسَنُ بْنُ عِيسَى، أَخْبَرَنَا ابْنُ الْمُبَارَكِ، أَخْبَرَنَا عَاصِمٌ، بِهَذَا الإِسْنَادِ ‏.‏ نَحْوَهُ ‏.‏" to "وحدثناه الحسن بن عيسي، اخبرنا ابن المبارك، اخبرنا عاصم، بهذا الاسناد . نحوه .",
    "وَحَدَّثَنَاهُ أَحْمَدُ بْنُ عُثْمَانَ النَّوْفَلِيُّ، حَدَّثَنَا أَبُو دَاوُدَ، حَدَّثَنَا شُعْبَةُ، بِهَذَا الإِسْنَادِ نَحْوَهُ ‏.‏" to "وحدثناه احمد بن عثمان النوفلي، حدثنا ابو داود، حدثنا شعبه، بهذا الاسناد نحوه .",
    "وَحَدَّثَنَاهُ أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا ابْنُ أَبِي زَائِدَةَ، عَنْ عُبَيْدِ اللَّهِ، بِهَذَا الإِسْنَادِ مِثْلَهُ." to "وحدثناه ابو بكر بن ابي شيبه، حدثنا ابن ابي زايده، عن عبيد الله، بهذا الاسناد مثله.",
    "وَحَدَّثَنَاهُ أَبُو الرَّبِيعِ، وَأَبُو كَامِلٍ قَالاَ حَدَّثَنَا حَمَّادٌ، حَدَّثَنَا أَيُّوبُ، بِهَذَا الإِسْنَادِ نَحْوَهُ ‏.‏" to "وحدثناه ابو الربيع، وابو كامل قالا حدثنا حماد، حدثنا ايوب، بهذا الاسناد نحوه .",
    "وَحَدَّثَنَا حَسَنٌ الْحُلْوَانِيُّ، حَدَّثَنَا أَبُو عَاصِمٍ، عَنِ ابْنِ جُرَيْجٍ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "وحدثنا حسن الحلواني، حدثنا ابو عاصم، عن ابن جريج، بهذا الاسناد مثله .",
    "وَحَدَّثَنَاهُ مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ سَعِيدٍ، عَنْ قَتَادَةَ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "وحدثناه محمد بن المثني، حدثنا ابن ابي عدي، عن سعيد، عن قتاده، بهذا الاسناد مثله .",
    "وَحَدَّثَنِيهِ زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثنيه زهير بن حرب، حدثنا جرير، عن الاعمش، بهذا الاسناد .",
    "وَحَدَّثَنَا عَمْرٌو النَّاقِدُ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا مَنْصُورٌ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "وحدثنا عمرو الناقد، حدثنا هشيم، اخبرنا منصور، بهذا الاسناد مثله .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، حَدَّثَنَا هِشَامٌ، بِهَذَا الإِسْنَادِ مِثْلَهُ." to "حدثنا محمد بن المثني، حدثنا يحيي بن سعيد، حدثنا هشام، بهذا الاسناد مثله.",
    "حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الرَّحْمَنِ، حَدَّثَنَا سُفْيَانُ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "حدثنا محمد بن المثني، حدثنا عبد الرحمن، حدثنا سفيان، بهذا الاسناد مثله .",
    "حَدَّثَنَا يَحْيَى بْنُ يَحْيَى، قَالَ أَخْبَرَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ مَعْمَرٍ، عَنِ الزُّهْرِيِّ، بِهَذَا الإِسْنَادِ ‏.‏" to "حدثنا يحيي بن يحيي، قال اخبرنا سفيان بن عيينه، عن معمر، عن الزهري، بهذا الاسناد .",
    "حَدَّثَنَاهُ ابْنُ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا عُبَيْدُ اللَّهِ، بِهَذَا الإِسْنَادِ مِثْلَهُ وَلَمْ يَذْكُرْ فِي النَّفَلِ ‏.‏" to "حدثناه ابن نمير، حدثنا ابي، حدثنا عبيد الله، بهذا الاسناد مثله ولم يذكر في النفل .",
    "وَحَدَّثَنَا عَمْرٌو النَّاقِدُ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، حَدَّثَنَا هِشَامُ بْنُ حَسَّانَ، بِهَذَا الإِسْنَادِ نَحْوَهُ ‏.‏" to "وحدثنا عمرو الناقد، حدثنا يزيد بن هارون، حدثنا هشام بن حسان، بهذا الاسناد نحوه .",
    "وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعٌ، وَأَبُو مُعَاوِيَةَ عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ نَحْوَهُ ‏.‏" to "وحدثنا ابو بكر بن ابي شيبه، حدثنا وكيع، وابو معاويه عن الاعمش، بهذا الاسناد نحوه .",
    "وَحَدَّثَنَاهُ يَحْيَى بْنُ يَحْيَى، أَخْبَرَنَا خَالِدُ بْنُ عَبْدِ اللَّهِ، عَنْ يُونُسَ، بِهَذَا الإِسْنَادِ." to "وحدثناه يحيي بن يحيي، اخبرنا خالد بن عبد الله، عن يونس، بهذا الاسناد.",
    "وَحَدَّثَنَاهُ إِسْحَاقُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا حَمَّادُ بْنُ مَسْعَدَةَ، حَدَّثَنَا يَزِيدُ، عَنْ سَلَمَةَ، بِمِثْلِهِ ‏.‏" to "وحدثناه اسحاق بن ابراهيم، حدثنا حماد بن مسعده، حدثنا يزيد، عن سلمه، بمثله .",
    "وَحَدَّثَنَاهُ الْوَلِيدُ بْنُ شُجَاعٍ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ عَاصِمٍ، فِي هَذَا الإِسْنَادِ\n بِمِثْلِهِ ‏.‏" to "وحدثناه الوليد بن شجاع، حدثنا علي بن مسهر، عن عاصم، في هذا الاسناد\n بمثله .",
    "وَحَدَّثَنِيهِ يَحْيَى بْنُ حَبِيبٍ، حَدَّثَنَا رَوْحٌ، حَدَّثَنَا شُعْبَةُ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثنيه يحيي بن حبيب، حدثنا روح، حدثنا شعبه، بهذا الاسناد .",
    "وَحَدَّثَنِيهِ أَبُو الطَّاهِرِ، أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي مَالِكُ بْنُ أَنَسٍ، بِهَذَا الإِسْنَادِ\n مِثْلَهُ ‏.‏" to "وحدثنيه ابو الطاهر، اخبرنا ابن وهب، اخبرني مالك بن انس، بهذا الاسناد\n مثله .",
    "وَحَدَّثَنِي حَجَّاجُ بْنُ الشَّاعِرِ، حَدَّثَنَا سَهْلُ بْنُ حَمَّادٍ، حَدَّثَنَا شُعْبَةُ، بِهَذَا الإِسْنَادِ\n مِثْلَهُ ‏.‏" to "وحدثني حجاج بن الشاعر، حدثنا سهل بن حماد، حدثنا شعبه، بهذا الاسناد\n مثله .",
    "وَحَدَّثَنِيهِ أَبُو سَعِيدٍ الأَشَجُّ، حَدَّثَنَا حَفْصٌ، - يَعْنِي ابْنَ غِيَاثٍ - عَنْ عَاصِمٍ، بِهَذَا\n الإِسْنَادِ نَحْوَهُ ‏.‏" to "وحدثنيه ابو سعيد الاشج، حدثنا حفص، - يعني ابن غياث - عن عاصم، بهذا\n الاسناد نحوه .",
    "وَحَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ، حَدَّثَنَا يَحْيَى، عَنْ عُبَيْدِ اللَّهِ، بِمِثْلِهِ فِي هَذَا الإِسْنَادِ\n ‏.‏" to "وحدثنا عبيد الله بن سعيد، حدثنا يحيي، عن عبيد الله، بمثله في هذا الاسناد\n .",
    "وَحَدَّثَنَاهُ ابْنُ أَبِي عُمَرَ، حَدَّثَنَا الثَّقَفِيُّ، عَنْ أَيُّوبَ، بِهَذَا الإِسْنَادِ نَحْوَهُ ‏.‏" to "وحدثناه ابن ابي عمر، حدثنا الثقفي، عن ايوب، بهذا الاسناد نحوه .",
    "وَحَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنِي عَبْدُ الرَّزَّاقِ، أَخْبَرَنِي ابْنُ جُرَيْجٍ، بِهَذَا الإِسْنَادِ\n مِثْلَهُ ‏.‏" to "وحدثنا عبد بن حميد، اخبرني عبد الرزاق، اخبرني ابن جريج، بهذا الاسناد\n مثله .",
    "وَحَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ شُعْبَةَ، فِي هَذَا الإِسْنَادِ ‏.‏" to "وحدثنا محمد بن المثني، حدثنا يحيي بن سعيد، عن شعبه، في هذا الاسناد .",
    "وَحَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا زُهَيْرٌ، حَدَّثَنَا سُلَيْمَانُ الأَعْمَشُ، بِهَذَا الإِسْنَادِ مِثْلَهُ\n ‏.‏" to "وحدثنا احمد بن يونس، حدثنا زهير، حدثنا سليمان الاعمش، بهذا الاسناد مثله\n .",
    "وَحَدَّثَنِيهِ مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الرَّحْمَنِ، حَدَّثَنَا سُفْيَانُ، بِهَذَا الإِسْنَادِ وَزَادَ\nفَأَدَعُهَا ‏.‏" to "وحدثنيه محمد بن المثني، حدثنا عبد الرحمن، حدثنا سفيان، بهذا الاسناد وزاد\nفادعها .",
    "حَدَّثَنَا عُقْبَةُ بْنُ مُكْرَمٍ الْعَمِّيُّ، حَدَّثَنَا أَبُو عَاصِمٍ، عَنِ ابْنِ جُرَيْجٍ، بِهَذَا الإِسْنَادِ مِثْلَهُ\n‏.‏" to "حدثنا عقبه بن مكرم العمي، حدثنا ابو عاصم، عن ابن جريج، بهذا الاسناد مثله\n.",
    "وَحَدَّثَنِيهِ إِسْمَاعِيلُ بْنُ سَالِمٍ، أَخْبَرَنَا هُشَيْمٌ، أَخْبَرَنَا سَيَّارٌ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثنيه اسماعيل بن سالم، اخبرنا هشيم، اخبرنا سيار، بهذا الاسناد .",
    "وَحَدَّثَنَاهُ عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "وحدثناه عبد بن حميد، اخبرنا عبد الرزاق، اخبرنا معمر، بهذا الاسناد مثله .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، قَالَ حَدَّثَنَا أَبِي، حَدَّثَنَا مِسْعَرٌ، بِهَذَا الإِسْنَادِ\n مِثْلَهُ ‏.‏" to "حدثنا محمد بن عبد الله بن نمير، قال حدثنا ابي، حدثنا مسعر، بهذا الاسناد\n مثله .",
    "وَحَدَّثَنَاهُ عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ مِثْلَهُ\n ‏.‏" to "وحدثناه عثمان بن ابي شيبه، قال حدثنا جرير، عن الاعمش، بهذا الاسناد مثله\n .",
    "وَحَدَّثَنَاهُ أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثناه ابو كريب، حدثنا ابو معاويه، بهذا الاسناد .",
    "وَحَدَّثَنَاهُ شَيْبَانُ بْنُ فَرُّوخَ، حَدَّثَنَا سَلاَّمُ بْنُ مِسْكِينٍ، حَدَّثَنَا ثَابِتٌ الْبُنَانِيُّ، عَنْ \n أَنَسٍ، بِمِثْلِهِ ‏.‏" to "وحدثناه شيبان بن فروخ، حدثنا سلام بن مسكين، حدثنا ثابت البناني، عن \n انس، بمثله .",
    "وَحَدَّثَنِي أَبُو الطَّاهِرِ، أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، بِهَذَا الإِسْنَادِ\n نَحْوَهُ ‏.‏" to "وحدثني ابو الطاهر، اخبرنا ابن وهب، اخبرني يونس، عن ابن شهاب، بهذا الاسناد\n نحوه .",
    "وَحَدَّثَنِيهِ مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الصَّمَدِ، حَدَّثَنَا الْمُثَنَّى، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثنيه محمد بن المثني، حدثنا عبد الصمد، حدثنا المثني، بهذا الاسناد .",
    "وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا ابْنُ عُلَيَّةَ، عَنْ خَالِدٍ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثنا ابو بكر بن ابي شيبه، حدثنا ابن عليه، عن خالد، بهذا الاسناد .",
    "وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، عَنْ عُمَرَ بْنِ سَعِيدٍ، فِي\n هَذَا الإِسْنَادِ بِمِثْلِهِ ‏.‏" to "وحدثنا اسحاق بن ابراهيم، اخبرنا عيسي بن يونس، عن عمر بن سعيد، في\n هذا الاسناد بمثله .",
    "حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، فِي هَذَا الإِسْنَادِ ‏.‏" to "حدثنا عبيد الله بن معاذ، حدثنا ابي، حدثنا شعبه، في هذا الاسناد .",
    "وَحَدَّثَنَاهُ إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا أَسْبَاطُ بْنُ مُحَمَّدٍ، عَنْ زَكَرِيَّاءَ، بِهَذَا الإِسْنَادِ\n مِثْلَهُ ‏.‏" to "وحدثناه اسحاق بن ابراهيم، اخبرنا اسباط بن محمد، عن زكرياء، بهذا الاسناد\n مثله .",
    "حَدَّثَنَاهُ عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدَةُ، عَنْ هِشَامٍ، بِهَذَا الإِسْنَادِ ‏.‏" to "حدثناه عثمان بن ابي شيبه، حدثنا عبده، عن هشام، بهذا الاسناد .",
    "حَدَّثَنَاهُ مُحَمَّدُ بْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ قَالاَ حَدَّثَنَا أَبُو دَاوُدَ، حَدَّثَنَا شُعْبَةُ، فِي هَذَا\n الإِسْنَادِ ‏.‏" to "حدثناه محمد بن المثني، وابن، بشار قالا حدثنا ابو داود، حدثنا شعبه، في هذا\n الاسناد .",
    "حَدَّثَنِي سُوَيْدُ بْنُ سَعِيدٍ، حَدَّثَنَا مَرْوَانُ بْنُ مُعَاوِيَةَ، عَنْ عَاصِمٍ الأَحْوَلِ، بِهَذَا الإِسْنَادِ\n ‏.‏" to "حدثني سويد بن سعيد، حدثنا مروان بن معاويه، عن عاصم الاحول، بهذا الاسناد\n .",
    "حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، حَدَّثَنَا هِشَامٌ، بِهَذَا الإِسْنَادِ ‏.‏" to "حدثنا ابو كريب، حدثنا ابو معاويه، حدثنا هشام، بهذا الاسناد .",
    "وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ\n ‏.‏" to "وحدثنا ابو بكر بن ابي شيبه، حدثنا حفص بن غياث، عن الاعمش، بهذا الاسناد\n .",
    "حَدَّثَنَا أَبُو بَكْرِ بْنُ نَافِعٍ، حَدَّثَنَا بَهْزٌ، حَدَّثَنَا حَمَّادٌ، بِهَذَا الإِسْنَادِ نَحْوَهُ ‏.‏" to "حدثنا ابو بكر بن نافع، حدثنا بهز، حدثنا حماد، بهذا الاسناد نحوه .",
    "حَدَّثَنَاهُ مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ بَكْرٍ، حَدَّثَنَا سَعِيدٌ، عَنْ قَتَادَةَ، بِهَذَا الإِسْنَادِ\n ‏.‏" to "حدثناه محمد بن بشار، حدثنا محمد بن بكر، حدثنا سعيد، عن قتاده، بهذا الاسناد\n .",
    "وَحَدَّثَنَاهُ أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، وَوَكِيعٌ، عَنْ هِشَامٍ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثناه ابو كريب، حدثنا ابو معاويه، ووكيع، عن هشام، بهذا الاسناد .",
    "وَحَدَّثَنِيهِ زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا إِسْحَاقُ بْنُ يُوسُفَ الأَزْرَقُ، حَدَّثَنَا زَكَرِيَّاءُ، بِهَذَا\n الإِسْنَادِ ‏.‏" to "وحدثنيه زهير بن حرب، حدثنا اسحاق بن يوسف الازرق، حدثنا زكرياء، بهذا\n الاسناد .",
    "وَحَدَّثَنَاهُ إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا الثَّقَفِيُّ، أَخْبَرَنَا أَيُّوبُ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثناه اسحاق بن ابراهيم، اخبرنا الثقفي، اخبرنا ايوب، بهذا الاسناد .",
    "وَحَدَّثَنَاهُ مُحَمَّدُ بْنُ عَبْدِ الأَعْلَى، حَدَّثَنَا الْمُعْتَمِرُ، عَنْ أَبِيهِ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثناه محمد بن عبد الاعلي، حدثنا المعتمر، عن ابيه، بهذا الاسناد .",
    "حَدَّثَنَا أَبُو سَعِيدٍ الأَشَجُّ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "حدثنا ابو سعيد الاشج، حدثنا وكيع، حدثنا الاعمش، بهذا الاسناد مثله .",
    "حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، بِالإِسْنَادَيْنِ جَمِيعًا كَرِوَايَةِ\n ابْنِ نُمَيْرٍ ‏.‏" to "حدثنا اسحاق بن ابراهيم، حدثنا جرير، عن الاعمش، بالاسنادين جميعا كروايه\n ابن نمير .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنِي وَهْبُ بْنُ جَرِيرٍ، أَخْبَرَنَا شُعْبَةُ، بِهَذَا الإِسْنَادِ نَحْوَهُ\n ‏.‏" to "حدثنا محمد بن المثني، حدثني وهب بن جرير، اخبرنا شعبه، بهذا الاسناد نحوه\n .",
    "وَحَدَّثَنِيهِ أَبُو كَامِلٍ، حَدَّثَنَا حَمَّادٌ، بِهَذَا الإِسْنَادِ نَحْوَهُ ‏.‏" to "وحدثنيه ابو كامل، حدثنا حماد، بهذا الاسناد نحوه .",
    "وَحَدَّثَنَاهُ ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا الصَّدُوقُ الأَمِينُ الْوَلِيدُ بْنُ حَرْبٍ، بِهَذَا\n الإِسْنَادِ ‏.‏" to "وحدثناه ابن ابي عمر، حدثنا سفيان، حدثنا الصدوق الامين الوليد بن حرب، بهذا\n الاسناد .",
    "وَحَدَّثَنَاهُ أَبُو كُرَيْبٍ، حَدَّثَنَا ابْنُ نُمَيْرٍ، حَدَّثَنَا هِشَامٌ، بِهَذَا الإِسْنَادِ ‏.‏" to "وحدثناه ابو كريب، حدثنا ابن نمير، حدثنا هشام، بهذا الاسناد .",
    "وَحَدَّثَنَاهُ أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا هِشَامٌ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "وحدثناه ابو بكر بن ابي شيبه، حدثنا ابو اسامه، حدثنا هشام، بهذا الاسناد مثله .",
    "وَحَدَّثَنِي حَجَّاجُ بْنُ الشَّاعِرِ، حَدَّثَنَا شَبَابَةُ، قَالَ قَالَ شُعْبَةُ وَقَدْ لَقِيتُ شَهْرًا فَلَمْ أَعْتَدَّ بِهِ ‏.‏" to "وحدثني حجاج بن الشاعر، حدثنا شبابه، قال قال شعبه وقد لقيت شهرا فلم اعتد به .",
    "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا مُحَمَّدُ بْنُ جَابِرٍ، عَنْ قَيْسِ بْنِ طَلْقٍ، بِإِسْنَادِهِ وَمَعْنَاهُ وَقَالَ فِي الصَّلاَةِ ‏.‏" to "حدثنا مسدد، حدثنا محمد بن جابر، عن قيس بن طلق، باسناده ومعناه وقال في الصلاه .",
    "حَدَّثَنَا يُوسُفُ بْنُ مُوسَى، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ خَيْثَمَةَ، قَالَ حَيَاتُهَا أَنْ تَجِدَ، حَرَّهَا ‏.‏" to "حدثنا يوسف بن موسي، حدثنا جرير، عن منصور، عن خيثمه، قال حياتها ان تجد، حرها .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، نَحْوَهُ ‏.‏" to "حدثنا محمد بن يحيي، حدثنا عبد الرزاق، عن معمر، نحوه .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ سُلَيْمَانَ الأَنْبَارِيُّ، قَالَ قَالَ وَكِيعٌ وَابْنُ عُيَيْنَةَ يَعْنِي يَسْتَغْنِي بِهِ ‏.‏" to "حدثنا محمد بن سليمان الانباري، قال قال وكيع وابن عيينه يعني يستغني به .",
    "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، عَنْ جَعْفَرٍ، بِإِسْنَادِهِ زَادَ ‏\n\"‏ فَانْحَرُوا فِي رِحَالِكُمْ ‏\"‏ ‏.‏" to "حدثنا مسدد، حدثنا حفص بن غياث، عن جعفر، باسناده زاد \n\" فانحروا في رحالكم \" .",
    "حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا هِشَامٌ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، فِي أَمْرُكِ بِيَدِكِ ‏.‏ قَالَ ثَلاَثٌ ‏.‏" to "حدثنا مسلم بن ابراهيم، حدثنا هشام، عن قتاده، عن الحسن، في امرك بيدك . قال ثلاث .",
    "حَدَّثَنَا الْقَعْنَبِيُّ، عَنْ مَالِكٍ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ عِدَّةُ الْمُخْتَلِعَةِ حَيْضَةٌ ‏.‏" to "حدثنا القعنبي، عن مالك، عن نافع، عن ابن عمر، قال عده المختلعه حيضه .",
    "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا عَبْدُ الْوَارِثِ، عَنْ أَيُّوبَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ نُهِيَ عَنْ رُكُوبِ الْجَلاَّلَةِ" to "حدثنا مسدد، حدثنا عبد الوارث، عن ايوب، عن نافع، عن ابن عمر، قال نهي عن ركوب الجلاله",
    "حَدَّثَنَا ابْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الأَعْلَى، عَنْ سَعِيدٍ، عَنْ قَتَادَةَ، قَالَ الْجَلَبُ وَالْجَنَبُ فِي الرِّهَانِ ‏.‏" to "حدثنا ابن المثني، حدثنا عبد الاعلي، عن سعيد، عن قتاده، قال الجلب والجنب في الرهان .",
    "حَدَّثَنَا هَنَّادٌ، عَنِ ابْنِ الْمُبَارَكِ، عَنْ أَبِي عَوَانَةَ، عَنْ عَاصِمِ بْنِ كُلَيْبٍ، بِإِسْنَادِهِ وَمَعْنَاهُ ‏.‏" to "حدثنا هناد، عن ابن المبارك، عن ابي عوانه، عن عاصم بن كليب، باسناده ومعناه .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، قَالَ سُئِلَ سُفْيَانُ عَنْ تَفْسِيرِ، هَذَا فَقَالَ إِذَا أَسْلَمَ فَلاَ جِزْيَةَ عَلَيْهِ ‏.‏" to "حدثنا محمد بن كثير، قال سيل سفيان عن تفسير، هذا فقال اذا اسلم فلا جزيه عليه .",
    "حَدَّثَنَا حَفْصُ بْنُ عُمَرَ، حَدَّثَنَا جَامِعُ بْنُ مَطَرٍ، عَنْ عَلْقَمَةَ بْنِ وَائِلٍ، بِإِسْنَادِهِ مِثْلَهُ ‏.‏" to "حدثنا حفص بن عمر، حدثنا جامع بن مطر، عن علقمه بن وايل، باسناده مثله .",
    "حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنَا وَكِيعٌ، عَنْ شُعْبَةَ، قَالَ كَانَ سُفْيَانُ أَحْفَظَ مِنِّي ‏.‏" to "حدثنا احمد بن حنبل، حدثنا وكيع، عن شعبه، قال كان سفيان احفظ مني .",
    "حَدَّثَنَا ابْنُ الْمُصَفَّى، حَدَّثَنَا بَقِيَّةُ، حَدَّثَنَا الزُّبَيْدِيُّ، عَنْ نَافِعٍ، بِإِسْنَادِ أَيُّوبَ وَمَعْنَاهُ ‏.‏" to "حدثنا ابن المصفي، حدثنا بقيه، حدثنا الزبيدي، عن نافع، باسناد ايوب ومعناه .",
    "حَدَّثَنَا جَعْفَرُ بْنُ مُسَافِرٍ، حَدَّثَنَا ابْنُ أَبِي فُدَيْكٍ، عَنْ هِشَامِ بْنِ سَعْدٍ، بِإِسْنَادِهِ مِثْلَهُ ‏.‏" to "حدثنا جعفر بن مسافر، حدثنا ابن ابي فديك، عن هشام بن سعد، باسناده مثله .",
    "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا عِيسَى بْنُ يُونُسَ، عَنِ الْجُرَيْرِيِّ، بِإِسْنَادِهِ نَحْوَهُ ‏.‏" to "حدثنا مسدد، حدثنا عيسي بن يونس، عن الجريري، باسناده نحوه .",
    "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا أَبُو عَوَانَةَ، قَالَ ثَوْبَ مَذَلَّةٍ ‏.‏" to "حدثنا مسدد، حدثنا ابو عوانه، قال ثوب مذله .",
    "حَدَّثَنَا ابْنُ السَّرْحِ، قَالَ رَأَيْتُ فِي كِتَابِ خَالِي عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، بِإِسْنَادِهِ وَمَعْنَاهُ ‏.‏" to "حدثنا ابن السرح، قال رايت في كتاب خالي عن عقيل، عن ابن شهاب، باسناده ومعناه .",
    "حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، عَنْ عَنْبَسَةَ، عَنْ يُونُسَ، عَنِ الزُّهْرِيِّ، قَالَ وَسَلاَحُ قَرِيبٌ مِنْ خَيْبَرَ ‏.‏" to "حدثنا احمد بن صالح، عن عنبسه، عن يونس، عن الزهري، قال وسلاح قريب من خيبر .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ عِيسَى بْنِ الطَّبَّاعِ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَبْدِ الْقُدُّوسِ، قَالَ زِيَادٌ سِيمِينْ كُوشْ ‏.‏" to "حدثنا محمد بن عيسي بن الطباع، حدثنا عبد الله بن عبد القدوس، قال زياد سيمين كوش .",
    "حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، عَنْ مُحَمَّدِ بْنِ جَعْفَرٍ، عَنْ شُعْبَةَ، ك ف ر ‏.‏" to "حدثنا محمد بن المثني، عن محمد بن جعفر، عن شعبه، ك ف ر .",
    "وَبِهَذَا الإِسْنَادِ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\"‏ لَيْسَ عَلَى الْخَائِنِ قَطْعٌ ‏\"‏ ‏.‏" to "وبهذا الاسناد قال قال رسول الله صلي الله عليه وسلم \n\" ليس علي الخاين قطع \" .",
    "حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، عَنْ هُشَيْمٍ، عَنِ ابْنِ شُبْرُمَةَ، عَنِ الشَّعْبِيِّ، بِنَحْوٍ مِنْهُ ‏.‏" to "حدثنا وهب بن بقيه، عن هشيم، عن ابن شبرمه، عن الشعبي، بنحو منه .",
    "حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا هِشَامٌ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، قَالَ لاَ يُقَادُ الْحُرُّ بِالْعَبْدِ ‏.‏" to "حدثنا مسلم بن ابراهيم، حدثنا هشام، عن قتاده، عن الحسن، قال لا يقاد الحر بالعبد .",
    "حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا وُهَيْبٌ، عَنْ خَالِدٍ، بِهَذَا الإِسْنَادِ نَحْوَ مَعْنَاهُ ‏.‏" to "حدثنا موسي بن اسماعيل، حدثنا وهيب، عن خالد، بهذا الاسناد نحو معناه .",
    "حَدَّثَنَا وَاصِلُ بْنُ عَبْدِ الأَعْلَى، عَنِ ابْنِ فُضَيْلٍ، عَنِ الأَعْمَشِ، بِهَذَا قَالَ كَأَنَّهُ يُحِبُّ الْجَمَاعَةَ ‏.‏" to "حدثنا واصل بن عبد الاعلي، عن ابن فضيل، عن الاعمش، بهذا قال كانه يحب الجماعه .",
    "حَدَّثَنَا عِيسَى بْنُ أَبِي عِيسَى السَّيْلَحِينِيُّ، عَنْ أَبِي الْمُغِيرَةِ، كَمَا قَالَ ابْنُ الْمُصَفَّى ‏.‏" to "حدثنا عيسي بن ابي عيسي السيلحيني، عن ابي المغيره، كما قال ابن المصفي .",
    "وَحَدَّثَنَا قُتَيْبَةُ، عَنْ مَالِكٍ، نَحْوَهُ ‏.‏" to "وحدثنا قتيبه، عن مالك، نحوه .",
    "حَدَّثَنَا قُتَيْبَةُ، عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، نَحْوَهُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏" to "حدثنا قتيبه، عن مالك، عن ابن شهاب، نحوه . قال ابو عيسي هذا حديث حسن صحيح .",
    "وَقَالَ مُحَمَّدٌ حَدَّثَنَا ابْنُ نُمَيْرٍ، عَنْ عُبَيْدِ اللَّهِ بْنِ مُوسَى، عَنْ غَالِبٍ، بِهَذَا ‏.‏" to "وقال محمد حدثنا ابن نمير، عن عبيد الله بن موسي، عن غالب، بهذا .",
    "حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ أَبِي جَمْرَةَ، عَنِ ابْنِ عَبَّاسٍ، نَحْوَهُ ‏.‏" to "حدثنا قتيبه، حدثنا حماد بن زيد، عن ابي جمره، عن ابن عباس، نحوه .",
    "حَدَّثَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا بَكْرُ بْنُ مُضَرَ الْقُرَشِيُّ، عَنِ ابْنِ الْهَادِ، نَحْوَهُ ‏.‏" to "حدثنا قتيبه، قال حدثنا بكر بن مضر القرشي، عن ابن الهاد، نحوه .",
    "أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "اخبرنا اسحاق بن ابراهيم، قال حدثنا ابو معاويه، عن الاعمش، بهذا الاسناد مثله .",
    "قَالَ إِسْحَاقُ أَنْبَأَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "قال اسحاق انبانا ابو معاويه، عن الاعمش، بهذا الاسناد مثله .",
    "أَخْبَرَنَا سُوَيْدُ بْنُ نَصْرٍ، قَالَ أَنْبَأَنَا عَبْدُ اللَّهِ، عَنِ الْجُرَيْرِيِّ، عَنْ أَبِي نَضْرَةَ، نَحْوَهُ ‏.‏" to "اخبرنا سويد بن نصر، قال انبانا عبد الله، عن الجريري، عن ابي نضره، نحوه .",
    "أَخْبَرَنَا أَحْمَدُ بْنُ سُلَيْمَانَ، عَنْ أَبِي دَاوُدَ، عَنْ سُفْيَانَ، عَنْ سِمَاكٍ، عَنْ عِكْرِمَةَ، مُرْسَلٌ ‏.‏" to "اخبرنا احمد بن سليمان، عن ابي داود، عن سفيان، عن سماك، عن عكرمه، مرسل .",
    "أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا النَّضْرُ، عَنْ شُعْبَةَ، بِهَذَا الإِسْنَادِ مِثْلَهُ ‏.‏" to "اخبرنا اسحاق بن ابراهيم، قال انبانا النضر، عن شعبه، بهذا الاسناد مثله .",
    "أَخْبَرَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، عَنْ عَبْدِ الأَعْلَى، نَحْوَهُ ‏.‏" to "اخبرنا محمد بن المثني، عن عبد الاعلي، نحوه .",
    "أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا عَبْدُ الرَّزَّاقِ، بِهَذَا الإِسْنَادِ مِثْلَهُ وَلَمْ يَرْفَعْهُ ‏.‏" to "اخبرنا اسحاق بن ابراهيم، قال انبانا عبد الرزاق، بهذا الاسناد مثله ولم يرفعه .",
    "أَخْبَرَنَا قُتَيْبَةُ، عَنْ مَالِكٍ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم نَهَى عَنِ النَّجْشِ ‏.‏" to "اخبرنا قتيبه، عن مالك، عن نافع، عن ابن عمر، ان النبي صلي الله عليه وسلم نهي عن النجش .",
    "أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا بِشْرٌ، عَنْ يُونُسَ، عَنِ الْحَسَنِ، وَمُحَمَّدٍ، قَالاَ التَّرَجُّلُ غِبٌّ ‏.‏" to "اخبرنا قتيبه، قال حدثنا بشر، عن يونس، عن الحسن، ومحمد، قالا الترجل غب .",
    "أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا الْمُعْتَمِرُ، عَنْ بُرْدٍ، عَنْ مَكْحُولٍ، قَالَ كُلُّ مُسْكِرٍ حَرَامٌ ‏.‏" to "اخبرنا اسحاق بن ابراهيم، قال حدثنا المعتمر، عن برد، عن مكحول، قال كل مسكر حرام .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ يَقُولُ دُلُوكُ الشَّمْسِ مَيْلُهَا ‏.‏" to "حدثني يحيي، عن مالك، عن نافع، ان عبد الله بن عمر، كان يقول دلوك الشمس ميلها .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ ابْنَ عُمَرَ، كَانَ يَنَامُ جَالِسًا ثُمَّ يُصَلِّي وَلاَ يَتَوَضَّأُ ‏.‏" to "وحدثني عن مالك، عن نافع، ان ابن عمر، كان ينام جالسا ثم يصلي ولا يتوضا .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ يَأْخُذُ الْمَاءَ بِأَصْبُعَيْهِ لأُذُنَيْهِ ‏.‏" to "حدثني يحيي، عن مالك، عن نافع، ان عبد الله بن عمر، كان ياخذ الماء باصبعيه لاذنيه .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ الأَسْلَمِيِّ، أَنَّهُ قَالَ رَأَيْتُ سَعِيدَ" to "حدثني يحيي، عن مالك، عن عبد الرحمن بن حرمله الاسلمي، انه قال رايت سعيد",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ، كَانَ يُصَلِّي فِي الثَّوْبِ الْوَاحِدِ ‏.‏" to "وحدثني عن مالك، انه بلغه ان جابر بن عبد الله، كان يصلي في الثوب الواحد .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّهُ كَانَ يُسَافِرُ إِلَى خَيْبَرَ فَيَقْصُرُ الصَّلاَةَ ‏.‏" to "وحدثني عن مالك، عن نافع، عن ابن عمر، انه كان يسافر الي خيبر فيقصر الصلاه .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّهُ كَانَ يُسَافِرُ مَعَ ابْنِ عُمَرَ الْبَرِيدَ فَلاَ يَقْصُرُ الصَّلاَةَ ‏.‏" to "وحدثني عن مالك، عن نافع، انه كان يسافر مع ابن عمر البريد فلا يقصر الصلاه .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ أَبِيهِ، عَنْ عُمَرَ بْنِ الْخَطَّابِ، مِثْلَ ذَلِكَ ‏.‏" to "وحدثني عن مالك، عن زيد بن اسلم، عن ابيه، عن عمر بن الخطاب، مثل ذلك .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ يَسْتَتِرُ بِرَاحِلَتِهِ إِذَا صَلَّى ‏.‏" to "حدثني يحيي، عن مالك، انه بلغه ان عبد الله بن عمر، كان يستتر براحلته اذا صلي .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، أَنَّ أَبَاهُ، كَانَ يُصَلِّي فِي الصَّحْرَاءِ إِلَى غَيْرِ سُتْرَةٍ ‏.‏" to "وحدثني عن مالك، عن هشام بن عروه، ان اباه، كان يصلي في الصحراء الي غير ستره .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ لاَ يَقْنُتُ فِي شَىْءٍ مِنَ الصَّلاَةِ ‏.‏" to "حدثني يحيي، عن مالك، عن نافع، ان عبد الله بن عمر، كان لا يقنت في شيء من الصلاه .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ ابْنَ عُمَرَ، لَمْ يَكُنْ يَلْتَفِتُ فِي صَلاَتِهِ ‏.‏" to "وحدثني عن مالك، عن نافع، ان ابن عمر، لم يكن يلتفت في صلاته .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ، كَانَ يَدِبُّ رَاكِعًا ‏.‏" to "وحدثني عن مالك، انه بلغه ان عبد الله بن مسعود، كان يدب راكعا .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ أَبَا بَكْرٍ، وَعُمَرَ، كَانَا يَفْعَلاَنِ ذَلِكَ ‏.‏" to "وحدثني عن مالك، انه بلغه ان ابا بكر، وعمر، كانا يفعلان ذلك .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صلى" to "وحدثني عن مالك، عن هشام بن عروه، عن ابيه، عن عايشه، زوج النبي صلي",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، قَالَ اللَّهُمَّ اجْعَلْنِي مِنْ أَئِمَّةِ الْمُتَّقِينَ ‏.‏" to "وحدثني عن مالك، انه بلغه ان عبد الله بن عمر، قال اللهم اجعلني من ايمه المتقين .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، أَنَّهُ قَالَ الْمَشْىُ خَلْفَ الْجَنَازَةِ مِنْ خَطَإِ السُّنَّةِ ‏.‏" to "وحدثني عن مالك، عن ابن شهاب، انه قال المشي خلف الجنازه من خطا السنه .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ لاَ يَقْرَأُ فِي الصَّلاَةِ عَلَى الْجَنَازَةِ ‏.‏" to "وحدثني عن مالك، عن نافع، ان عبد الله بن عمر، كان لا يقرا في الصلاه علي الجنازه .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عَائِشَةَ، وَحَفْصَةَ، زَوْجَىِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِ ذَلِكَ ‏.‏" to "وحدثني عن مالك، عن ابن شهاب، عن عايشه، وحفصه، زوجي النبي صلي الله عليه وسلم بمثل ذلك .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ لاَ يَصُومُ فِي السَّفَرِ ‏.‏" to "وحدثني عن مالك، عن نافع، ان عبد الله بن عمر، كان لا يصوم في السفر .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ يَكْرَهُ لُبْسَ الْمِنْطَقَةِ لِلْمُحْرِمِ ‏.‏" to "حدثني يحيي، عن مالك، عن نافع، ان عبد الله بن عمر، كان يكره لبس المنطقه للمحرم .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، أَهَلَّ مِنَ الْفُرْعِ ‏.‏" to "وحدثني عن مالك، عن نافع، ان عبد الله بن عمر، اهل من الفرع .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنِ الثِّقَةِ، عِنْدَهُ أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، أَهَلَّ مِنْ إِيلْيَاءَ ‏.‏" to "وحدثني عن مالك، عن الثقه، عنده ان عبد الله بن عمر، اهل من ايلياء .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَهَلَّ مِنَ الْجِعِرَّانَةِ بِعُمْرَةٍ ‏.‏" to "وحدثني عن مالك، انه بلغه ان رسول الله صلي الله عليه وسلم اهل من الجعرانه بعمره .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ يُصَلِّي فِي مَسْجِدِ ذِي الْحُلَيْفَةِ" to "وحدثني عن مالك، عن نافع، ان عبد الله بن عمر، كان يصلي في مسجد ذي الحليفه",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، كَانَ يَقُولُ لاَ يَنْكِحِ الْمُحْرِمُ وَلاَ" to "وحدثني عن مالك، عن نافع، ان عبد الله بن عمر، كان يقول لا ينكح المحرم ولا",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، أَنَّ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ، أَهْدَى جَمَلاً فِي حَجٍّ أَوْ عُمْرَةٍ ‏.‏" to "وحدثني عن مالك، عن يحيي بن سعيد، ان عمر بن عبد العزيز، اهدي جملا في حج او عمره .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ ثَوْرِ بْنِ زَيْدٍ الدِّيلِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، مِثْلَ ذَلِكَ ‏.‏" to "وحدثني عن مالك، عن ثور بن زيد الديلي، عن عبد الله بن عباس، مثل ذلك .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَقُولُ ‏\n\"‏ لاَ وَمُقَلِّبِ الْقُلُوبِ ‏\"‏ ‏.‏" to "وحدثني عن مالك، انه بلغه ان رسول الله صلي الله عليه وسلم كان يقول \n\" لا ومقلب القلوب \" .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ، كَانَ يَقُولُ مَا فَرَى الأَوْدَاجَ فَكُلُوهُ ‏.‏" to "وحدثني عن مالك، انه بلغه ان عبد الله بن عباس، كان يقول ما فري الاوداج فكلوه .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ الْقَاسِمَ بْنَ مُحَمَّدٍ، كَانَ يَكْرَهُ مَا قَتَلَ الْمِعْرَاضُ وَالْبُنْدُقَةُ ‏.‏" to "وحدثني عن مالك، انه بلغه ان القاسم بن محمد، كان يكره ما قتل المعراض والبندقه .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَمَّنْ سَمِعَ نَافِعًا، يَقُولُ قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ وَإِنْ أَكَلَ وَإِنْ لَمْ يَأْكُلْ ‏.‏" to "وحدثني عن مالك، عمن سمع نافعا، يقول قال عبد الله بن عمر وان اكل وان لم ياكل .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّهُ عُقَّ عَنْ حَسَنٍ، وَحُسَيْنٍ، ابْنَىْ عَلِيِّ بْنِ أَبِي طَالِبٍ ‏.‏" to "وحدثني عن مالك، انه بلغه انه عق عن حسن، وحسين، ابني علي بن ابي طالب .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ، طَلَّقَ امْرَأَةً لَهُ فَمَتَّعَ بِوَلِيدَةٍ ‏.‏" to "حدثني يحيي، عن مالك، انه بلغه ان عبد الرحمن بن عوف، طلق امراه له فمتع بوليده .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ سَمِعَ ابْنَ شِهَابٍ، يَقُولُ عِدَّةُ الْمُطَلَّقَةِ الأَقْرَاءُ وَإِنْ تَبَاعَدَتْ ‏.‏" to "وحدثني عن مالك، انه سمع ابن شهاب، يقول عده المطلقه الاقراء وان تباعدت .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ كَانَ لاَ يَعْزِلُ وَكَانَ يَكْرَهُ الْعَزْلَ ‏.‏" to "وحدثني عن مالك، عن نافع، عن عبد الله بن عمر، انه كان لا يعزل وكان يكره العزل .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ أَنَّ عُثْمَانَ بْنَ عَفَّانَ، كَانَ يَنْهَى عَنِ الْحُكْرَةِ، ‏.‏" to "وحدثني عن مالك، انه بلغه ان عثمان بن عفان، كان ينهي عن الحكره، .",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، أَنَّ رَسُولَ اللَّهِ" to "حدثني يحيي، عن مالك، عن زيد بن اسلم، عن سعيد بن المسيب، ان رسول الله",
    "حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ بَلَغَهُ ‏.‏ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم نَهَى عَنْ بَيْعَتَيْنِ فِي بَيْعَةٍ ‏.‏" to "حدثني يحيي، عن مالك، انه بلغه . ان رسول الله صلي الله عليه وسلم نهي عن بيعتين في بيعه .",
    "قَالَ مَالِكٌ عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم نَهَى عَنِ النَّجْشِ ‏.‏" to "قال مالك عن نافع، عن عبد الله بن عمر، ان رسول الله صلي الله عليه وسلم نهي عن النجش .",
    "وَحَدَّثَنِي مَالِكٌ، أَنَّهُ بَلَغَهُ أَنَّ عُمَرَ بْنَ الْخَطَّابِ، قَالَ لاَ تَجُوزُ شَهَادَةُ خَصْمٍ وَلاَ ظَنِينٍ ‏.‏" to "وحدثني مالك، انه بلغه ان عمر بن الخطاب، قال لا تجوز شهاده خصم ولا ظنين .",
    "وَحَدَّثَنِي مَالِكٌ، عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ أَعْتَقَ وَلَدَ زِنًا وَأُمَّهُ ‏.‏" to "وحدثني مالك، عن نافع، عن عبد الله بن عمر، انه اعتق ولد زنا وامه .",
    "وَحَدَّثَنِي مَالِكٌ، عَنْ أَبِي جَعْفَرٍ الْقَارِيِّ، أَنَّهُ قَالَ رَأَيْتُ عَبْدَ اللَّهِ بْنَ عُمَرَ يَشْرَبُ قَائِمًا ‏.‏" to "وحدثني مالك، عن ابي جعفر القاري، انه قال رايت عبد الله بن عمر يشرب قايما .",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، عَنْ أَبِيهِ، أَنَّهُ كَانَ يَشْرَبُ قَائِمًا ‏.‏" to "وحدثني عن مالك، عن عامر بن عبد الله بن الزبير، عن ابيه، انه كان يشرب قايما .",
    "باب مَا جَاءَ فِي نَزْعِ الْمَعَالِيقِ وَالْجَرَسِ مِنَ الْعُنُقِ" to "باب ما جاء في نزع المعاليق والجرس من العنق",
    "وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ نَافِعٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، اكْتَوَى مِنَ اللَّقْوَةِ وَرُقِيَ مِنَ الْعَقْرَبِ ‏.‏" to "وحدثني عن مالك، عن نافع، ان عبد الله بن عمر، اكتوي من اللقوه ورقي من العقرب .",
    "حَدَّثَنِي مَالِكٌ، عَنْ عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، أَنَّهُ كَانَ إِذَا سَمِعَ الرَّعْدَ، تَرَكَ الْحَدِيثَ" to "حدثني مالك، عن عامر بن عبد الله بن الزبير، انه كان اذا سمع الرعد، ترك الحديث",
    "وعن أبي هريرة أن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏والكلمة الطيبة صدقة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ وهو بعض حديث تقدم بطوله‏.‏" to "وعن ابي هريره ان النبي صلي الله عليه وسلم قال: \n\"والكلمه الطيبه صدقه\" ((متفق عليه)) وهو بعض حديث تقدم بطوله.",
    "وعن عائشة رضي الله عنها قالت‏:‏ كان كلام رسول الله صلى الله عليه وسلم كلاماً فصلاً يفهمه كل من يسمعه‏.‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏" to "وعن عايشه رضي الله عنها قالت: كان كلام رسول الله صلي الله عليه وسلم كلاما فصلا يفهمه كل من يسمعه. ((رواه ابو داود)).",
    "عن جابر رضي الله عنه ‏:‏ كان النبي صلى الله عليه وسلم الله عليه وسلم إذا كان يوم عيد خالف الطريق‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "عن جابر رضي الله عنه : كان النبي صلي الله عليه وسلم الله عليه وسلم اذا كان يوم عيد خالف الطريق. ((رواه البخاري)).",
    "عن عمر بن أبى سلمة رضى الله عنهما قال‏:‏ قال لي رسول الله صلى الله عليه وسلم‏:‏‏\n\"‏سم الله وكل بيمينك، وكل مما يليك‏\"‏.‏ ((متفق عليه))" to "عن عمر بن ابي سلمه رضي الله عنهما قال: قال لي رسول الله صلي الله عليه وسلم:\n\"سم الله وكل بيمينك، وكل مما يليك\". ((متفق عليه))",
    "وعن أبى هريرة رضى الله عنه قال‏:‏ ‏\n\"‏ما عاب رسول الله صلى الله عليه وسلم طعاماً قط، إن اشتهاه أكله، وإن كرهه تركه‏\"‏ ‏.‏ ((متفق عليه))" to "وعن ابي هريره رضي الله عنه قال: \n\"ما عاب رسول الله صلي الله عليه وسلم طعاما قط، ان اشتهاه اكله، وان كرهه تركه\" . ((متفق عليه))",
    "عن أبى جحيفة وهب بن عبد الله رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏ لا آكل متكئاً‏\"‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏" to "عن ابي جحيفه وهب بن عبد الله رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم: \n\" لا اكل متكيا\".((رواه البخاري))",
    "وعن أنس رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم جالساً مقعياً يأكل تمراً.‏ ‏‏((رواه مسلم))‏" to "وعن انس رضي الله عنه قال: رايت رسول الله صلي الله عليه وسلم جالسا مقعيا ياكل تمرا. ((رواه مسلم))",
    "وعن كعب بن مالك رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم يأكل بثلاث أصابع ، فإذا فرغ لعقها‏.‏‏‏((رواه مسلم))‏\n ‏" to "وعن كعب بن مالك رضي الله عنه قال: رايت رسول الله صلي الله عليه وسلم ياكل بثلاث اصابع ، فاذا فرغ لعقها.((رواه مسلم))\n ",
    "عن أنس رضى الله عنه أن رسول الله صلى الله عليه وسلم كان يتنفس في الشراب ثلاثاً‏.‏((متفق عليه))" to "عن انس رضي الله عنه ان رسول الله صلي الله عليه وسلم كان يتنفس في الشراب ثلاثا.((متفق عليه))",
    "وعن أبى قتادة رضى الله عنه أن النبي صلى الله عليه وسلم نهى أن يتنفس في الإناء‏.‏‏((متفق عليه))" to "وعن ابي قتاده رضي الله عنه ان النبي صلي الله عليه وسلم نهي ان يتنفس في الاناء.((متفق عليه))",
    "عن أبى سعيد الخدرى رضى الله عنه قال ‏:‏ نهى رسول الله عن اختناث الأسقية ‏:‏ يعنى‏:‏ أن تكسر أفواهها، ويشرب منها‏.‏((متفق عليه))" to "عن ابي سعيد الخدري رضي الله عنه قال : نهي رسول الله عن اختناث الاسقيه : يعني: ان تكسر افواهها، ويشرب منها.((متفق عليه))",
    "وعن أبى هريرة رضى الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن يشرب من في السقاء أو القربة.‏((متفق عليه))" to "وعن ابي هريره رضي الله عنه قال: نهي رسول الله صلي الله عليه وسلم ان يشرب من في السقاء او القربه.((متفق عليه))",
    "وعن ابن عباس رضى الله عنهما أن النبي صلى الله عليه وسلم نهى أن يتنفس في الإناء، أو ينفخ فيه‏.‏((رواه الترمذي))" to "وعن ابن عباس رضي الله عنهما ان النبي صلي الله عليه وسلم نهي ان يتنفس في الاناء، او ينفخ فيه.((رواه الترمذي))",
    "وعن ابن عباس رضى الله عنهما قال‏:‏ سقيت النبي صلى الله عليه وسلم من زمزم، فشرب وهو قائم ‏.‏((متفق عليه))" to "وعن ابن عباس رضي الله عنهما قال: سقيت النبي صلي الله عليه وسلم من زمزم، فشرب وهو قايم .((متفق عليه))",
    "وعن ابن عمر رضى الله عنهما قال‏:‏كنا نأكل على عهد رسول الله صلى الله عليه وسلم ونحن نمشى ، ونشرب ونحن قيام‏.‏((رواه الترمذي))" to "وعن ابن عمر رضي الله عنهما قال:كنا ناكل علي عهد رسول الله صلي الله عليه وسلم ونحن نمشي ، ونشرب ونحن قيام.((رواه الترمذي))",
    "وعن عمرو بن شعيب عن أبيه عن جده رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم يشرب قائماً أو قاعداً‏.‏ ((رواه الترمذي))" to "وعن عمرو بن شعيب عن ابيه عن جده رضي الله عنه قال: رايت رسول الله صلي الله عليه وسلم يشرب قايما او قاعدا. ((رواه الترمذي))",
    "وعن أبى هريرة رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ لا يشربن أحد منكم قائماً، فمن نسى فليستقئ‏\"‏‏‏‏. ((رواه مسلم))‏" to "وعن ابي هريره رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم : لا يشربن احد منكم قايما، فمن نسي فليستقي\". ((رواه مسلم))",
    "عن أبى قتادة رضى الله عنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏ ساقي القوم آخرهم شرباً‏\"‏. ((رواه الترمذي))" to "عن ابي قتاده رضي الله عنه عن النبي صلي الله عليه وسلم قال: \n\" ساقي القوم اخرهم شربا\". ((رواه الترمذي))",
    "وعن عبد الله بن زيد رضى الله عنه قال‏:‏ أتانا النبي صلى الله عليه وسلم، فأخرجنا له ماء في نور من صفر فتوضأ‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏" to "وعن عبد الله بن زيد رضي الله عنه قال: اتانا النبي صلي الله عليه وسلم، فاخرجنا له ماء في نور من صفر فتوضا.((رواه البخاري))",
    "وعن أبى رمثة رفاعة التيمى رضى الله عنه قال‏:‏ رأيت رسول الله صلى الله عليه وسلم وعليه ثوبان أخضران‏.‏((رواه أبو داود والترمذي))" to "وعن ابي رمثه رفاعه التيمي رضي الله عنه قال: رايت رسول الله صلي الله عليه وسلم وعليه ثوبان اخضران.((رواه ابو داود والترمذي))",
    "وعن جابر رضى الله عنه ، أن رسول الله صلى الله عليه وسلم دخل يوم فتح مكة وعليه عمامة سوداء‏.‏‏‏((رواه مسلم))‏" to "وعن جابر رضي الله عنه ، ان رسول الله صلي الله عليه وسلم دخل يوم فتح مكه وعليه عمامه سوداء.((رواه مسلم))",
    "وعنها قالت‏:‏ خرج رسول الله صلى الله عليه وسلم ذات غداة، وعليه مرط مرحل من شعر أسود‏.‏‏‏((رواه مسلم))‏" to "وعنها قالت: خرج رسول الله صلي الله عليه وسلم ذات غداه، وعليه مرط مرحل من شعر اسود.((رواه مسلم))",
    "عن أم سلمة رضى الله عنها قالت‏:‏ كان أحب الثياب إلى رسول الله صلى الله عليه وسلم القميص‏.‏((رواه أبو داود والترمذي))" to "عن ام سلمه رضي الله عنها قالت: كان احب الثياب الي رسول الله صلي الله عليه وسلم القميص.((رواه ابو داود والترمذي))",
    "عن أسماء بنت يزيد الأنصارية رضى الله عنها قالت‏:‏ كان كم قميص رسول الله صلى الله عليه وسلم إلى الرسغ.‏((رواه أبو داود والترمذي))" to "عن اسماء بنت يزيد الانصاريه رضي الله عنها قالت: كان كم قميص رسول الله صلي الله عليه وسلم الي الرسغ.((رواه ابو داود والترمذي))",
    "وعن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\n\"‏لا ينظر الله يوم القيامة إلى من جر إزاره بطراً‏\"‏.‏((متفق عليه))" to "وعن ابي هريره رضي الله عنه ان رسول الله صلي الله عليه وسلم قال: \n\"لا ينظر الله يوم القيامه الي من جر ازاره بطرا\".((متفق عليه))",
    "وعنه عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏ما أسفل من الكعبين من الإزار ففي النار‏\"‏.‏‏‏((‏رواه البخارى‏)‏‏)‏‏" to "وعنه عن النبي صلي الله عليه وسلم قال: \n\"ما اسفل من الكعبين من الازار ففي النار\".((رواه البخاري))",
    "وعن أنس رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏من لبس الحرير في الدنيا لم يلبسه في الآخرة‏\"‏.((متفق عليه))  \n‏" to "وعن انس رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم: \n\"من لبس الحرير في الدنيا لم يلبسه في الاخره\".((متفق عليه))  \n",
    "عن معاوية رضى الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏لا تركبوا الخز ولا النمار‏\"‏‏.‏ ((رواه أبو داود))" to "عن معاويه رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم : \n\"لا تركبوا الخز ولا النمار\". ((رواه ابو داود))",
    "وعن أبى هريرة رضى الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\n\"‏إذا قام أحدكم من مجلس، ثم رجع إليه، فهو أحق به‏\"‏. ((رواه مسلم))." to "وعن ابي هريره رضي الله عنه ان رسول الله صلي الله عليه وسلم قال: \n\"اذا قام احدكم من مجلس، ثم رجع اليه، فهو احق به\". ((رواه مسلم)).",
    "عن أنس رضي الله عنه أنه مر على صبيان، فسلم عليهم، وقال‏:‏ كان رسول الله صلى الله عليه وسلم يفعله” ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "عن انس رضي الله عنه انه مر علي صبيان، فسلم عليهم، وقال: كان رسول الله صلي الله عليه وسلم يفعله” ((متفق عليه))",
    "وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\"‏إذا سلم عليكم أهل الكتاب فقولوا‏:‏ وعليكم” ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن انس رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم: \"اذا سلم عليكم اهل الكتاب فقولوا: وعليكم” ((متفق عليه))",
    "وعن سهل بن سعد قال‏:‏ قال رسول الله صلى  الله عليه وسلم  ‏:‏ ‏\n\"‏إنما جعل الاستئذان من أجل البصر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن سهل بن سعد قال: قال رسول الله صلي  الله عليه وسلم  : \n\"انما جعل الاستيذان من اجل البصر\" ((متفق عليه)).",
    "عن أبي الخطاب قتادة قال‏:‏ قلت لأنس‏:‏ أكانت المصافحة في أصحاب رسول الله صلى  الله عليه وسلم ‏؟‏ قال‏:‏ نعم‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "عن ابي الخطاب قتاده قال: قلت لانس: اكانت المصافحه في اصحاب رسول الله صلي  الله عليه وسلم ؟ قال: نعم\" ((رواه البخاري)).",
    "وعن ابن عمر، رضي الله عنهما، قصة قال فيها‏:‏ فدنونا من النبي صلى الله عليه وسلم  فقبلنا يده‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏" to "وعن ابن عمر، رضي الله عنهما، قصه قال فيها: فدنونا من النبي صلي الله عليه وسلم  فقبلنا يده\" ((رواه ابو داود)).",
    "وعن أبي سعيد الخدري رضي الله عنه قال‏:‏ قال رسول الله صلى  الله عليه وسلم  ‏:‏ “لقنوا موتاكم لا إله إلا الله‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن ابي سعيد الخدري رضي الله عنه قال: قال رسول الله صلي  الله عليه وسلم  : “لقنوا موتاكم لا اله الا الله\" ((رواه مسلم)).",
    "وعنه قال‏:‏ كان رسول الله صلى  الله عليه وسلم  يتخلف في المسير، فيزجي الضعيف ويردف ويدعو له، ‏(‏‏(‏رواه أبو داود بإسناد حسن‏)‏‏)‏‏.‏" to "وعنه قال: كان رسول الله صلي  الله عليه وسلم  يتخلف في المسير، فيزجي الضعيف ويردف ويدعو له، ((رواه ابو داود باسناد حسن)).",
    "عن جابر رضي الله عنه قال‏:‏ كنا إذا صعدنا كبرنا، وإذا نزلنا سبحنا‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "عن جابر رضي الله عنه قال: كنا اذا صعدنا كبرنا، واذا نزلنا سبحنا. ((رواه البخاري)).",
    "عن كعب بن مالك رضي الله عنه أن رسول الله صلى  الله عليه وسلم  كان إذا قدم من سفر بدأ بالمسجد فركع فيه ركعتين ‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏" to "عن كعب بن مالك رضي الله عنه ان رسول الله صلي  الله عليه وسلم  كان اذا قدم من سفر بدا بالمسجد فركع فيه ركعتين . ((متفق عليه)) .",
    "- وعن عثمان بن عفان رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏خيركم من تعلم القرآن وعلمه‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "- وعن عثمان بن عفان رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم : \n\"خيركم من تعلم القران وعلمه\" ((رواه البخاري)).",
    "وعنه قال‏:‏ سمعت خليلي صلى الله عليه وسلم يقول‏:‏ ‏\n\"‏تبلغ الحلية من المؤمن حيث يبلغ الوضوء‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعنه قال: سمعت خليلي صلي الله عليه وسلم يقول: \n\"تبلغ الحليه من المومن حيث يبلغ الوضوء\" ((رواه مسلم)).",
    "عن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏‏\n\"‏من صلى البردين دخل الجنة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "عن ابي موسي رضي الله عنه ان رسول الله صلي الله عليه وسلم قال:\n\"من صلي البردين دخل الجنه\" ((متفق عليه)).",
    "وعن بريدة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏‏\n\"‏من ترك صلاة العصر فقد حبط عمله‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "وعن بريده رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم :\n\"من ترك صلاه العصر فقد حبط عمله\" ((رواه البخاري)).",
    "وعن أبي هريرة رضي الله عنه قال قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏وسطوا الإمام، وسدوا الخلل‏\"‏ ‏(‏‏(‏رواه أبو داود‏)‏‏)‏‏.‏" to "وعن ابي هريره رضي الله عنه قال قال رسول الله صلي الله عليه وسلم: \n\"وسطوا الامام، وسدوا الخلل\" ((رواه ابو داود)).",
    "عن عائشة رضي الله عنها، أن النبي صلى الله عليه وسلم كان لا يدع أربعًا قبل الظهر، وركعتين قبل الغداة ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "عن عايشه رضي الله عنها، ان النبي صلي الله عليه وسلم كان لا يدع اربعا قبل الظهر، وركعتين قبل الغداه ((رواه البخاري)).",
    "وعنها قالت‏:‏ لم يكن النبي، صلى الله عليه وسلم على شيء من النوافل أشد تعاهدًا منه على ركعتي الفجر‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعنها قالت: لم يكن النبي، صلي الله عليه وسلم علي شيء من النوافل اشد تعاهدا منه علي ركعتي الفجر\". ((متفق عليه)).",
    "عن عائشة رضي الله عنها قالت‏:‏ كان النبي صلى الله عليه وسلم إذا صلى ركعتي الفجر، اضطجع على شقه الأيمن‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "عن عايشه رضي الله عنها قالت: كان النبي صلي الله عليه وسلم اذا صلي ركعتي الفجر، اضطجع علي شقه الايمن. ((رواه البخاري)).",
    "عن ابن عمر رضي الله عنهما قال‏:‏ صليت مع رسول الله صلى الله عليه وسلم ركعتين قبل الظهر، وركعتين بعدها‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "عن ابن عمر رضي الله عنهما قال: صليت مع رسول الله صلي الله عليه وسلم ركعتين قبل الظهر، وركعتين بعدها. ((متفق عليه))",
    "وعن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان لا يدع أربعًا قبل الظهر‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "وعن عايشه رضي الله عنها ان النبي صلي الله عليه وسلم كان لا يدع اربعا قبل الظهر. ((رواه البخاري)).",
    "وعن علي بن أبي طالب رضي الله عنه أن النبي صلى الله عليه وسلم كان يصلي قبل العصر ركعتين‏.‏‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد صحيح‏)‏‏)‏‏.‏" to "وعن علي بن ابي طالب رضي الله عنه ان النبي صلي الله عليه وسلم كان يصلي قبل العصر ركعتين.\" ((رواه ابو داود باسناد صحيح)).",
    "- وعن أنس، رضي الله عنه قال‏:‏ لقد رأيت كبار أصحاب رسول الله صلى الله عليه وسلم يبتدرون السواري عند المغرب‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "- وعن انس، رضي الله عنه قال: لقد رايت كبار اصحاب رسول الله صلي الله عليه وسلم يبتدرون السواري عند المغرب. ((رواه البخاري)).",
    "وعن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم كان لا يصلي بعد الجمعة حتى ينصرف، فيصلي ركعتين في بيته‏. (‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن ابن عمر رضي الله عنهما، ان النبي صلي الله عليه وسلم كان لا يصلي بعد الجمعه حتي ينصرف، فيصلي ركعتين في بيته. ((رواه مسلم)).",
    "وعن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ اجلعوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن ابن عمر رضي الله عنهما عن النبي صلي الله عليه وسلم قال: اجلعوا من صلاتكم في بيوتكم، ولا تتخذوها قبورا\". ((متفق عليه)).",
    "وعن ابن عمر رضي الله عنهما، عن النبي صلى الله عليه وسلم‏:‏ ‏\n\"‏ اجعلوا آخر صلاتكم بالليل وترًا‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن ابن عمر رضي الله عنهما، عن النبي صلي الله عليه وسلم: \n\" اجعلوا اخر صلاتكم بالليل وترا\". ((متفق عليه))",
    "وعن أبي سعيد الخدري رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏أوتروا قبل أن تصبحوا‏\"‏‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن ابي سعيد الخدري رضي الله عنه ان النبي صلي الله عليه وسلم قال: \n\"اوتروا قبل ان تصبحوا\". ((رواه مسلم)).",
    "وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يصلي الضحى أربعًا ويزيد ما شاء الله ‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن عايشه رضي الله عنها قالت: كان رسول الله صلي الله عليه وسلم يصلي الضحي اربعا ويزيد ما شاء الله . ((رواه مسلم)).",
    "وعن جابر، رضي الله عنه قال‏:‏ أتيت النبي صلى الله عليه وسلم وهو في المسجد فقال‏:‏ ‏\n\"‏صلِ ركعتين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن جابر، رضي الله عنه قال: اتيت النبي صلي الله عليه وسلم وهو في المسجد فقال: \n\"صل ركعتين\" ((متفق عليه)).",
    "وعن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏\n\"‏إذا جاء أحدكم الجمعة، فليغتسل‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏" to "وعن ابن عمر رضي الله عنهما، ان رسول الله صلي الله عليه وسلم ، قال: \n\"اذا جاء احدكم الجمعه، فليغتسل\" ((متفق عليه)) .",
    "وعن أبي سعيد الخدري، رضي الله عنه، أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏\n\"‏غسل الجمعة واجب على كل محتلم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏" to "وعن ابي سعيد الخدري، رضي الله عنه، ان رسول الله صلي الله عليه وسلم ، قال: \n\"غسل الجمعه واجب علي كل محتلم\" ((متفق عليه)) .",
    "وعن علي رضي الله عنه، أن النبي صلى الله عليه وسلم، طرقه وفاطمة ليلا، فقال‏:‏ ‏\"‏ألا تصليان‏؟‏‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏ (20)" to "وعن علي رضي الله عنه، ان النبي صلي الله عليه وسلم، طرقه وفاطمه ليلا، فقال: \"الا تصليان؟\" ((متفق عليه)). (20)",
    "وعنه قال‏:‏ كان النبي صلى الله عليه وسلم ، يصلي من الليل مثنى مثنى، ويوتر بركعة‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏" to "وعنه قال: كان النبي صلي الله عليه وسلم ، يصلي من الليل مثني مثني، ويوتر بركعه. ((متفق عليه)) .",
    "وعنها أن النبي صلى الله عليه وسلم، كان ينام أول الليل، ويقوم آخره فيصلي‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏" to "وعنها ان النبي صلي الله عليه وسلم، كان ينام اول الليل، ويقوم اخره فيصلي. ((متفق عليه)) .",
    "وعن جابر رضي الله عنه قال‏:‏ سئل رسول الله صلى الله عليه وسلم ‏:‏ أي الصلاة أفضل‏؟‏ قال‏:‏ ‏\n\"‏طول القنوت‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن جابر رضي الله عنه قال: سيل رسول الله صلي الله عليه وسلم : اي الصلاه افضل؟ قال: \n\"طول القنوت\" ((رواه مسلم)).",
    "وعن عائشة رضي الله عنها قالت كان رسول الله صلى الله عليه وسلم إذا قام من الليل افتتح صلاته بركعتين خفيفتين ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن عايشه رضي الله عنها قالت كان رسول الله صلي الله عليه وسلم اذا قام من الليل افتتح صلاته بركعتين خفيفتين ((رواه مسلم)).",
    "وعن حذيفة رضي الله عنه، قال‏:‏ كان رسول الله صلى الله عليه وسلم، إذا قام من النوم يشوص فاه بالسواك‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن حذيفه رضي الله عنه، قال: كان رسول الله صلي الله عليه وسلم، اذا قام من النوم يشوص فاه بالسواك. ((متفق عليه))",
    "وعن أنس رضي الله عنه، قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏أكثرت عليكم في السواك‏\"‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "وعن انس رضي الله عنه، قال: قال رسول الله صلي الله عليه وسلم : \n\"اكثرت عليكم في السواك\" ((رواه البخاري)).",
    "وعن ابن عمر رضي الله عنهما، عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏أحفوا الشوارب وأعفوا اللحى‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏ ‏.‏" to "وعن ابن عمر رضي الله عنهما، عن النبي صلي الله عليه وسلم قال: \n\"احفوا الشوارب واعفوا اللحي\" ((متفق عليه)) .",
    "وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم إذا دخل العشر أحيا الليل وأيقظ أهله، وشد المئزر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن عايشه رضي الله عنها قالت: كان رسول الله صلي الله عليه وسلم اذا دخل العشر احيا الليل وايقظ اهله، وشد الميزر\" ((متفق عليه))",
    "عن أنس، رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏تسحروا فإن في السحور بركة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "عن انس، رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم: \n\"تسحروا فان في السحور بركه\" ((متفق عليه))",
    "وعن عمرو بن العاص رضي الله عنه أن رسول الله قال‏:‏ ‏\"‏فصل ما بين صيامنا وصيام أهل الكتاب أكلة السحر‏.‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن عمرو بن العاص رضي الله عنه ان رسول الله قال: \"فصل ما بين صيامنا وصيام اهل الكتاب اكله السحر. ((رواه مسلم)).",
    "عن سهل بن سعد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\n\"‏لا يزال الناس بخير ما عجلوا الفطر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "عن سهل بن سعد رضي الله عنه ان رسول الله صلي الله عليه وسلم قال: \n\"لا يزال الناس بخير ما عجلوا الفطر\" ((متفق عليه))",
    "وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يدركه الفجر وهو جنب من أهله ثم يغتسل ويصوم ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن عايشه رضي الله عنها قالت: كان رسول الله صلي الله عليه وسلم يدركه الفجر وهو جنب من اهله ثم يغتسل ويصوم ((متفق عليه))",
    "وعن عائشة وأم سلمة رضي الله عنهما قالتا‏:‏ كان رسول الله صلى الله عليه وسلم يصبح جنبًا من غير حلم ثم يصوم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن عايشه وام سلمه رضي الله عنهما قالتا: كان رسول الله صلي الله عليه وسلم يصبح جنبا من غير حلم ثم يصوم. ((متفق عليه))",
    "وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم صام يوم عاشوراء، وأمر بصيامه‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن ابن عباس رضي الله عنهما ان رسول الله صلي الله عليه وسلم صام يوم عاشوراء، وامر بصيامه. ((متفق عليه))",
    "وعن ابن عباس رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏لئن بقيت إلى قابل لأصومن التاسع‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن ابن عباس رضي الله عنهما قال: قال رسول الله صلي الله عليه وسلم: \n\"لين بقيت الي قابل لاصومن التاسع\" ((رواه مسلم)).",
    "وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يتحرى صوم الاثنين والخميس‏.‏ ‏(‏‏(‏رواه الترمذي وقال حديث حسن‏)‏‏)‏‏.‏" to "وعن عايشه رضي الله عنها قالت: كان رسول الله صلي الله عليه وسلم يتحري صوم الاثنين والخميس. ((رواه الترمذي وقال حديث حسن)).",
    "وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال‏:‏ قال رسول الله‏:‏ ‏\n\"‏صوم ثلاثة أيام من كل شهر صوم الدهر كله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال: قال رسول الله: \n\"صوم ثلاثه ايام من كل شهر صوم الدهر كله\" ((متفق عليه))",
    "عن ابن عمر رضي الله عنهما، قال‏:‏ كان رسول الله صلى الله عليه وسلم يعتكف العشر الأواخر من رمضان‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "عن ابن عمر رضي الله عنهما، قال: كان رسول الله صلي الله عليه وسلم يعتكف العشر الاواخر من رمضان. ((متفق عليه))",
    "وعنه قال سمعت رسول الله صلى الله عليه وسلم يقول‏:‏ ‏\n\"‏من حج، فلم يرفث ولم يفسق، رجع كيوم ولدته أمه‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعنه قال سمعت رسول الله صلي الله عليه وسلم يقول: \n\"من حج، فلم يرفث ولم يفسق، رجع كيوم ولدته امه\" ((متفق عليه))",
    "وعنها أن رسول الله صلى الله عليه وسلم، قال‏:‏ ‏\n\"‏ما من يوم أكثر من أن يعتق الله فيه عبدًا من النار من يوم عرفة‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعنها ان رسول الله صلي الله عليه وسلم، قال: \n\"ما من يوم اكثر من ان يعتق الله فيه عبدا من النار من يوم عرفه\" ((رواه مسلم)).",
    "وعن ابن عباس رضي الله عنهما، أن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏عمرة في رمضان تعدل عمرة أو حجة معي‏\"‏‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن ابن عباس رضي الله عنهما، ان النبي صلي الله عليه وسلم قال: \n\"عمره في رمضان تعدل عمره او حجه معي\". ((متفق عليه))",
    "وعن أنس رضي الله عنه، أن رسول الله صلى الله عليه وسلم حج على رحل وكانت زاملته‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏" to "وعن انس رضي الله عنه، ان رسول الله صلي الله عليه وسلم حج علي رحل وكانت زاملته. ((رواه البخاري)).",
    "وعن أبي ذر رضي الله عنه قال‏:‏ قلت يا رسول الله أي العمل أفضل‏؟‏ قال‏:‏ ‏\n\"‏الإيمان بالله والجهاد في سبيله‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن ابي ذر رضي الله عنه قال: قلت يا رسول الله اي العمل افضل؟ قال: \n\"الايمان بالله والجهاد في سبيله\" ((متفق عليه))",
    "وعن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\n\"‏لغدوة في سبيل الله أو روحة خير من الدنيا وما فيها‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن انس رضي الله عنه ان رسول الله صلي الله عليه وسلم قال: \n\"لغدوه في سبيل الله او روحه خير من الدنيا وما فيها\" ((متفق عليه))",
    "وعن أنس رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ ‏\n\"‏من طلب الشهادة صادقًا أعطيها ولو لم تصبه‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن انس رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم: \n\"من طلب الشهاده صادقا اعطيها ولو لم تصبه\" ((رواه مسلم)).",
    "وعن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\n\"‏الخيل معقود في نواصيها الخير إلى يوم القيامة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن ابن عمر رضي الله عنهما ان رسول الله صلي الله عليه وسلم قال: \n\"الخيل معقود في نواصيها الخير الي يوم القيامه\" ((متفق عليه))",
    "وعنه أنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏من عُلم الرمي ثم تركه فليس منا أو فقد عصى‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعنه انه قال: قال رسول الله صلي الله عليه وسلم : \n\"من علم الرمي ثم تركه فليس منا او فقد عصي\" ((رواه مسلم)).",
    "وعن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏قفلة كغزوة‏\"‏ ‏(‏‏(‏رواه أبو داود بإسناد جيد‏)‏‏)‏‏.‏" to "وعن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلي الله عليه وسلم قال: \n\"قفله كغزوه\" ((رواه ابو داود باسناد جيد)).",
    "وعنه وعن جابر، رضي الله عنهما أن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏الحرب خُدعة‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعنه وعن جابر، رضي الله عنهما ان النبي صلي الله عليه وسلم قال: \n\"الحرب خدعه\" ((متفق عليه))",
    "وعن عبد الله بن عمرو بن العاص، رضي الله عنهما قال‏:‏ قال رسول الله صلى الله عليه وسلم‏:‏ “من قتل دون ماله فهو شهيد‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن عبد الله بن عمرو بن العاص، رضي الله عنهما قال: قال رسول الله صلي الله عليه وسلم: “من قتل دون ماله فهو شهيد\" ((متفق عليه))",
    "عن معقل بن يسار رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏العبادة في الهرج كهجرة إلي‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "عن معقل بن يسار رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم : \n\"العباده في الهرج كهجره الي\" ((رواه مسلم)).",
    "وعن جابر، رضي الله عنه أن النبي صلى الله عليه وسلم اشترى منه بعيرًا فوزن له فأرجح‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن جابر، رضي الله عنه ان النبي صلي الله عليه وسلم اشتري منه بعيرا فوزن له فارجح. ((متفق عليه))",
    "وعن معاوية رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏من يرد الله به خيرًا يفقه في الدين‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏" to "وعن معاويه رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم : \n\"من يرد الله به خيرا يفقه في الدين\" ((متفق عليه))",
    "وعنها أن رسول الله صلى الله عليه وسلم كان يقول في ركوعه وسجوده‏:‏ ‏\n\"‏سبوح قدوس رب الملائكة والروح‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعنها ان رسول الله صلي الله عليه وسلم كان يقول في ركوعه وسجوده: \n\"سبوح قدوس رب الملايكه والروح\" ((رواه مسلم)).",
    "وعن عائشة رضي الله عنها قالت‏:‏ كان رسول الله صلى الله عليه وسلم يذكر الله تعالى على كل أحيانه‏.‏ رواه مسلم‏.‏" to "وعن عايشه رضي الله عنها قالت: كان رسول الله صلي الله عليه وسلم يذكر الله تعالي علي كل احيانه. رواه مسلم.",
    "وعن النعمان بن بشير رضي الله عنهما عن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏الدعاء هو العبادة‏\"‏‏.‏" to "وعن النعمان بن بشير رضي الله عنهما عن النبي صلي الله عليه وسلم قال: \n\"الدعاء هو العباده\".",
    "وعن ابن عمر رضي الله عنهما قال‏:‏ ما سمعت عمر رضي الله عنه يقول لشيء قط‏:‏ إني لأظنه كذا إلا كان كما يظن‏.‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏" to "وعن ابن عمر رضي الله عنهما قال: ما سمعت عمر رضي الله عنه يقول لشيء قط: اني لاظنه كذا الا كان كما يظن. ((رواه البخاري))",
    "وعن حذيفة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏لا يدخل الجنة نمام‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن حذيفه رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم : \n\"لا يدخل الجنه نمام\" ((متفق عليه)).",
    "وعن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال‏:‏ ‏\n\"‏كفى بالمرء كذبًا أن يحدث بكل ما سمع‏\"‏‏.‏ (‏‏(‏رواه مسلم‏)‏‏)‏‏" to "وعن ابي هريره رضي الله عنه ان النبي صلي الله عليه وسلم قال: \n\"كفي بالمرء كذبا ان يحدث بكل ما سمع\". ((رواه مسلم))",
    "وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\n\"‏لا ينبغي لصدِّيق أن يكون لعانًا‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن ابي هريره رضي الله عنه ان رسول الله صلي الله عليه وسلم قال: \n\"لا ينبغي لصديق ان يكون لعانا\" ((رواه مسلم)).",
    "وعن ابن مسعود رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ ‏\n\"‏سباب المسلم فسوق، وقتاله كفر‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن ابن مسعود رضي الله عنه قال: قال رسول الله صلي الله عليه وسلم : \n\"سباب المسلم فسوق، وقتاله كفر\" ((متفق عليه)).",
    "وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال‏:‏ ‏\n\"‏إياكم والظن، فإن الظن أكذب الحديث‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن ابي هريره رضي الله عنه ان رسول الله صلي الله عليه وسلم قال: \n\"اياكم والظن، فان الظن اكذب الحديث\" ((متفق عليه)).",
    "وعنه أن رسول الله صلى الله عليه وسلم ، قال‏:‏ ‏\n\"‏ لا تناجشوا‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعنه ان رسول الله صلي الله عليه وسلم ، قال: \n\" لا تناجشوا\" ((متفق عليه)).",
    "وعن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم نهى عن النَجَش، ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن ابن عمر رضي الله عنهما، ان النبي صلي الله عليه وسلم نهي عن النجش، ((متفق عليه)).",
    "وعن أنس رضي الله عنه قال‏:‏ نهى رسول الله صلى الله عليه وسلم أن تُصبر البهائم‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏  \nومعناه‏:‏ تحبس للقتل‏.‏" to "وعن انس رضي الله عنه قال: نهي رسول الله صلي الله عليه وسلم ان تصبر البهايم. ((متفق عليه)).  \nومعناه: تحبس للقتل.",
    "وعن جرير رضي الله عنه قال‏:‏ سألت رسول الله صلى الله عليه وسلم  عن نظر الفجأة فقال‏:‏ ‏\n\"‏اصرف بصرك‏\"‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏" to "وعن جرير رضي الله عنه قال: سالت رسول الله صلي الله عليه وسلم  عن نظر الفجاه فقال: \n\"اصرف بصرك\" ((رواه مسلم)).",
    "وعن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم  قال‏:‏ ‏\n\"‏لا يخلون أحدكم بامرأة إلا مع ذي محرم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "وعن ابن عباس رضي الله عنهما ان رسول الله صلي الله عليه وسلم  قال: \n\"لا يخلون احدكم بامراه الا مع ذي محرم\" ((متفق عليه)).",
    "عن ابن عمر رضي الله عنهما قال‏:‏ نهى رسول الله صلى الله عليه وسلم  عن القزع‏.‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏‏.‏" to "عن ابن عمر رضي الله عنهما قال: نهي رسول الله صلي الله عليه وسلم  عن القزع. ((متفق عليه)).",
